// Filter data for last month and calculate ROI metrics
const now = new Date();
const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const thisMonth = new Date(now.getFullYear(), now.getMonth(), 1);

const clientId = $env.CLIENT_ID;
const events = $input.all();

// Filter events for last month
const monthlyEvents = events.filter(event => {
  const eventDate = new Date(event.json.timestamp);
  return eventDate >= lastMonth && eventDate < thisMonth && 
         (event.json.clientId === clientId || !clientId);
});

// Attribution logic
const metrics = {
  totalRevenue: 0,
  revenueRecovered: 0,
  revenueGenerated: 0,
  jobsBooked: 0,
  jobsCompleted: 0,
  jobsLost: 0,
  timeSavedHours: 0,
  noShowsPrevented: 0,
  missedCallRecovery: { count: 0, revenue: 0 },
  leadQualification: { count: 0, revenue: 0 },
  reengagement: { count: 0, revenue: 0 },
  automationBreakdown: {}
};

monthlyEvents.forEach(event => {
  const value = parseFloat(event.json.estimatedJobValue) || 0;
  const status = event.json.status;
  const automation = event.json.automationResponsible;
  const source = event.json.leadSource;

  // Initialize automation breakdown
  if (!metrics.automationBreakdown[automation]) {
    metrics.automationBreakdown[automation] = {
      revenue: 0,
      count: 0,
      booked: 0,
      completed: 0
    };
  }

  // Count by status
  if (status === 'Booked') {
    metrics.jobsBooked++;
    metrics.automationBreakdown[automation].booked++;
  } else if (status === 'Completed') {
    metrics.jobsCompleted++;
    metrics.totalRevenue += value;
    metrics.automationBreakdown[automation].completed++;
    metrics.automationBreakdown[automation].revenue += value;
  } else if (status === 'Lost') {
    metrics.jobsLost++;
  }

  // Attribution by automation type
  if (automation && automation.toLowerCase().includes('missed call')) {
    metrics.missedCallRecovery.count++;
    if (status === 'Completed') {
      metrics.missedCallRecovery.revenue += value;
      metrics.revenueRecovered += value;
    }
    // Estimate 15 minutes saved per recovered call
    metrics.timeSavedHours += 0.25;
  }

  if (automation && automation.toLowerCase().includes('lead qual')) {
    metrics.leadQualification.count++;
    if (status === 'Completed') {
      metrics.leadQualification.revenue += value;
      metrics.revenueGenerated += value;
    }
    // Estimate 30 minutes saved per qualified lead
    metrics.timeSavedHours += 0.5;
  }

  if (automation && automation.toLowerCase().includes('reengag')) {
    metrics.reengagement.count++;
    if (status === 'Completed') {
      metrics.reengagement.revenue += value;
      metrics.revenueRecovered += value;
    }
    // Estimate 20 minutes saved per re-engagement
    metrics.timeSavedHours += 0.33;
  }

  if (automation && automation.toLowerCase().includes('appointment')) {
    // Estimate no-shows prevented (assume 10% reduction)
    if (status === 'Completed') {
      metrics.noShowsPrevented += 0.1;
    }
    // Estimate 10 minutes saved per booking
    metrics.timeSavedHours += 0.17;
  }

  metrics.automationBreakdown[automation].count++;
});

// Calculate conversion rate
const totalJobs = metrics.jobsBooked + metrics.jobsCompleted;
const conversionRate = totalJobs > 0 ? (metrics.jobsCompleted / totalJobs * 100).toFixed(1) : 0;

// Calculate average job value
const avgJobValue = metrics.jobsCompleted > 0 ? (metrics.totalRevenue / metrics.jobsCompleted).toFixed(2) : 0;

// Estimate labor cost saved (at $50/hour)
const laborCostSaved = (metrics.timeSavedHours * 50).toFixed(2);

// Previous month comparison (simplified - in production, query previous month data)
const previousMonthRevenue = metrics.totalRevenue * 0.85; // Simulated 15% growth
const revenueGrowth = ((metrics.totalRevenue - previousMonthRevenue) / previousMonthRevenue * 100).toFixed(1);

return [{
  json: {
    period: `${lastMonth.toLocaleString('default', { month: 'long' })} ${lastMonth.getFullYear()}`,
    clientId: clientId,
    metrics: metrics,
    summary: {
      totalRevenue: metrics.totalRevenue.toFixed(2),
      revenueRecovered: metrics.revenueRecovered.toFixed(2),
      revenueGenerated: metrics.revenueGenerated.toFixed(2),
      jobsCompleted: metrics.jobsCompleted,
      jobsBooked: metrics.jobsBooked,
      conversionRate: conversionRate,
      avgJobValue: avgJobValue,
      timeSavedHours: metrics.timeSavedHours.toFixed(1),
      laborCostSaved: laborCostSaved,
      noShowsPrevented: Math.round(metrics.noShowsPrevented),
      revenueGrowth: revenueGrowth
    },
    automationBreakdown: metrics.automationBreakdown,
    eventCount: monthlyEvents.length,
    calculatedAt: new Date().toISOString()
  }
}];

// Extract the executive summary from LLM response
const response = $input.first().json;
const executiveSummary = response.choices[0].message.content;

// Get the metrics from previous node
const metrics = $('Calculate ROI Metrics').first().json;

return [{
  json: {
    ...metrics,
    executiveSummary: executiveSummary,
    reportGenerated: new Date().toISOString()
  }
}];
